// ---------------------------------------------------------------------------
// Harness
// ---------------------------------------------------------------------------

fn repo_root() -> PathBuf {
    // tests/ -> epr-cli -> eprfs -> elohim -> <repo>
    // The live legs read the doc roots, every gospel CLAUDE.md, and the two in-repo legacy path
    // cites the LIVE_VERIFY documents carry today; a new legacy cite there must be declared here.
    // gate-reads: genesis/docs
    // gate-reads: .claude/memory
    // gate-reads: **/CLAUDE.md
    // gate-reads: elohim/sdk/domains/lamad/manifest.json
    // gate-reads: .claude/skills/memory-ceremony/SKILL.md
    let mut p = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    for _ in 0..3 {
        p = p
            .parent()
            .expect("manifest dir has ancestors")
            .to_path_buf();
    }
    p
}

fn fixtures() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/.cite-writer")
}

fn epr_binary() -> PathBuf {
    // Cargo owns artifact placement; the test executable need not sit beside epr.
    PathBuf::from(env!("CARGO_BIN_EXE_epr"))
}

fn copy_tree(src: &Path, dst: &Path) {
    std::fs::create_dir_all(dst).expect("create fixture copy");
    for entry in std::fs::read_dir(src).expect("read fixture dir") {
        let entry = entry.expect("fixture entry");
        let to = dst.join(entry.file_name());
        if entry.path().is_dir() {
            copy_tree(&entry.path(), &to);
        } else {
            std::fs::copy(entry.path(), &to).expect("copy fixture file");
        }
    }
}

/// A private copy of one fixture corpus. Returned as `(tempdir, root)` so the guard outlives use.
fn staged(name: &str) -> (tempfile::TempDir, PathBuf) {
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path().join("r");
    copy_tree(&fixtures().join(name), &root);
    (dir, root)
}

fn sha256_of(path: &Path) -> String {
    let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    let mut hasher = Sha256::new();
    hasher.update(&bytes);
    hasher
        .finalize()
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

fn run_cites(root: &Path, args: &[&str]) -> (i32, String) {
    let output = Command::new(epr_binary())
        .arg("flow")
        .arg("cites")
        .args(args)
        .arg("--root")
        .arg(root)
        .output()
        .expect("run epr flow cites");
    (
        output.status.code().unwrap_or(-1),
        String::from_utf8_lossy(&output.stdout).into_owned()
            + &String::from_utf8_lossy(&output.stderr),
    )
}

/// The four perturbations `seal` must repair. Applied only inside the frontmatter block.
fn perturb(root: &Path, mode: &str) {
    for doc in BASELINE_DOCS {
        let path = root.join(doc);
        let text = std::fs::read_to_string(&path).expect("read baseline doc");
        let lines: Vec<&str> = text.lines().collect();
        if lines.first().map(|l| l.trim()) != Some("---") {
            continue;
        }
        let Some(end) = lines
            .iter()
            .enumerate()
            .skip(1)
            .find(|(_, l)| l.trim() == "---")
            .map(|(i, _)| i)
        else {
            continue;
        };
        let mut out: Vec<String> = Vec::new();
        for (i, line) in lines.iter().enumerate() {
            let mut line = (*line).to_string();
            if i >= 1 && i < end {
                if mode == "no-id" && line.starts_with("id:") {
                    continue;
                }
                let is_item = line.trim_start().starts_with("- ");
                if is_item {
                    if let Some(at) = line.find("| path:") {
                        match mode {
                            "no-path" => {
                                let tail = trailing_quote(&line);
                                line = format!("{}{tail}", line[..at].trim_end());
                            }
                            "bad-path" => {
                                let tail = trailing_quote(&line);
                                line = format!("{}| path: WRONG/PLACE.md{tail}", &line[..at]);
                            }
                            "legacy" => {
                                let locator = line[at + "| path:".len()..]
                                    .trim()
                                    .trim_end_matches('"')
                                    .trim()
                                    .to_string();
                                line = format!("  - {locator}");
                            }
                            _ => {}
                        }
                    }
                }
            }
            out.push(line);
        }
        let mut joined = out.join("\n");
        if text.ends_with('\n') {
            joined.push('\n');
        }
        std::fs::write(&path, joined).expect("write perturbed doc");
    }
}

/// `"` when the envelope line is a quoted YAML scalar, otherwise empty.
fn trailing_quote(line: &str) -> &'static str {
    if line.trim_end().ends_with('"') {
        "\""
    } else {
        ""
    }
}

fn assert_seal_mode(mode: &str, expected: &[Row]) {
    let (_guard, root) = staged("tree");
    if mode != "pristine" {
        perturb(&root, mode);
    }
    for (doc, (want_sha, want_exit)) in BASELINE_DOCS.iter().zip(expected) {
        let (code, _) = run_cites(&root, &["seal", doc]);
        let got = sha256_of(&root.join(doc));
        assert_eq!(
            &got, want_sha,
            "[{mode}] {doc}: sealed bytes differ from the recorded cite-gen --seal output"
        );
        assert_eq!(
            code as u8, *want_exit,
            "[{mode}] {doc}: dissolution-gate exit differs from the oracle"
        );
    }
}

