#[test]
fn seal_reproduces_the_recorded_fixed_point_digests() {
    assert_seal_mode("pristine", SEAL_PRISTINE);
}

#[test]
fn seal_reassigns_a_stripped_id_exactly_as_the_oracle_does() {
    assert_seal_mode("no-id", SEAL_NO_ID);
}

#[test]
fn seal_repairs_a_wrong_path_locator_exactly_as_the_oracle_does() {
    assert_seal_mode("bad-path", SEAL_BAD_PATH);
}

#[test]
fn seal_restamps_a_missing_path_locator_exactly_as_the_oracle_does() {
    assert_seal_mode("no-path", SEAL_NO_PATH);
}

#[test]
fn seal_converts_a_downgraded_legacy_cite_exactly_as_the_oracle_does() {
    // The conversion path: description from the target's title, fingerprint recomputed from its
    // canonical body, locator restamped, envelope quoted at mint.
    assert_seal_mode("legacy", SEAL_LEGACY);
}

#[test]
fn seal_is_idempotent_on_an_already_sealed_document() {
    let (_guard, root) = staged("tree");
    for doc in BASELINE_DOCS {
        run_cites(&root, &["seal", doc]);
        let first = sha256_of(&root.join(doc));
        run_cites(&root, &["seal", doc]);
        assert_eq!(
            first,
            sha256_of(&root.join(doc)),
            "{doc}: seal is not idempotent"
        );
    }
}

