#[test]
fn stamp_refuses_a_run_whose_slug_index_is_ambiguous() {
    // Refusal 5 — two documents declaring the same `id:` make every verdict on that slug
    // untrustworthy, so the WHOLE run is refused by name. The oracle silently resolved the
    // collision by walk order; this is a deliberate divergence toward refusing rather than guessing.
    let (_guard, root) = staged("dup-id");
    let (code, out) = run_cites(&root, &["stamp", "--all", "--write"]);
    assert_ne!(code, 0, "an ambiguous slug index must refuse: {out}");
    assert!(out.contains("duplicate id:"), "{out}");
    assert!(
        out.contains("twin"),
        "the refusal must name the colliding slug: {out}"
    );
    assert!(
        out.contains("one.md") && out.contains("two.md"),
        "the refusal must name both: {out}"
    );
}

